import os
import re
import io
import six
import zipfile
import logging
from os import path
from . import builder
from .exception import CannotCheckBTSSMInstallerVersion, BTSSMExecutionError

if six.PY2:
    from cStringIO import StringIO
else:
    from io import StringIO


class BTSSM(object):

    CHMOD_CMD = "sudo chmod +x {}"
    INSTALL_CMD = 'sudo "{}" -i silent -DINSTALL_TYPE={} -DUSER_INSTALL_DIR="{}"'
    BTSSM_VERSION_REGEXP = '(^|/)(?P<version>(LN|FL|TL|WB).*?)(/|_[a-f0-9]{12}_)'
    NODE_MANAGERS_REGEXP = '.*/NodeManagers_.*.jar'
    UNZIP_PARAMETER_DICTIONARY = 'unzip -p "{}" com/nokia/em/bts/gui/lte/config/scf/*/LTEParameterDictionary.xml > "{}"'
    RELATIVE_JAVA_PATH = './jre/1_8_0/bin/java'

    def __init__(self, executor, install_location, temp_path):
        self._executor = executor
        self._temp_path = temp_path
        self._install_location = install_location

    def copy_local_installer(self, local_installer_path):
        """Method to copy provided installer to remote temporary path.

        :param string local_installer_path: Path to installer file.

        :return: Path where provided file is available after operation.
        :rtype: string
        """
        temp_path = os.path.join(self._temp_path, 'BTSSM_installer.bin')
        return self._executor.put_file(local_installer_path, temp_path)

    def add_exec_permissions(self, remote_path):
        """Method to change permission for installer.

        :param string remote_path: Path to file on remote machine.

        :return: Execution result.
        :rtype: string
        """
        cmd = BTSSM.CHMOD_CMD.format(remote_path)
        return self._executor.run(cmd)

    def install_btssm(self, remote_installer_path, mode):
        """Method to install provided installer.

        :param string remote_installer_path: Path to file on remote machine.
        :param string mode: Installation mode.

        :return: Installation result.
        :rtype: string
        """
        cmd = BTSSM.INSTALL_CMD.format(remote_installer_path, mode, self._install_location)
        try:
            return self._executor.run(cmd)
        except BTSSMExecutionError:
            self._remove_path(self._install_location)
            logging.warn("{} removed.".format(self._install_location))
            raise

    def save_snapshot(self, params, flag, **kwargs):
        """Method to save/download the snapshot.

        :param string params: List of parameters for the specified flag.
        :param list       flags:  Some flags needed to execute specified command properly e.g. -activate will be ['activate']

        :return: Save/Download result.
        :rtype: string
        """
        btssm_cmd_builder = builder.BTSSMCommandBuilder(self._install_location)
        cmd = btssm_cmd_builder.build(self.RELATIVE_JAVA_PATH, params, flags=flag)
        return self._executor.run(cmd, **kwargs)

    def get_installer_version(self, local_installer_path):
        """Returns version of provided BTSSM installer file.

        :param string local_installer_path: Path to file available locally.

        :return: Installer version.
        :rtype: string
        """
        version = self._extract_version_from_top_level(local_installer_path) or self._extract_version_from_node_managers(local_installer_path)
        if version is None:
            raise CannotCheckBTSSMInstallerVersion()
        return version

    def is_installed(self, filter_expression='*'):
        """Checks if BTSSM is installed on remote PC.

        :param string filter_expression: Bash regexp narrow possible results.

        :return: True if application is installed.
        :rtype: boolean
        """
        cmd = self._create_node_managers_check_command()
        out = self._executor.run(cmd)
        if out.strip() == 'missing':
            return False
        else:
            versions = self.get_installed_versions(filter_expression)
            return len(versions) > 0

    def get_installed_versions(self, filter_expression='*'):
        """Returns list of all installer BTSSM applications on remote PC.

        :param string filter_expression: Bash regexp narrow possible results.

        :return: Installed BTSSM applications.
        :rtype: list
        """
        ls_dir = path.join(self._install_location, 'NodeManagers')
        cmd = 'cd "{}"; ls -d {}'.format(ls_dir, filter_expression)
        out = self._executor.run_ignoring_rc(cmd)
        return out.strip().split()

    def get_parameter_dictionary(self, btssm_version, destination):
        """Extract parameters dictionary file from installed BTSSM application on remote PC.

        :param string btssm_version: BTSSM version.
        :param string destination: Path where dictionary will be saved.
        """
        jars_path = self._create_remote_jar_path(btssm_version)
        temp_path = os.path.join(self._temp_path, 'LTEParameterDictionary.xml')
        self._unpack_parameter_dictionary(jars_path, temp_path)
        self._executor.get_file(temp_path, destination)
        self._remove_path(temp_path)

    def _extract_version_from_top_level(self, installer_path):
        return self._get_version_from_names(zipfile.ZipFile(installer_path).namelist())

    def _extract_version_from_node_managers(self, installer_path):
        installer_zip_file = zipfile.ZipFile(installer_path)
        node_managers_jar_path = self._get_node_managers_jar_path(installer_zip_file)
        if node_managers_jar_path is None:
            return None
        node_managers_jar_zip_file = self._get_nested_zip_file(installer_zip_file, node_managers_jar_path)
        return self._get_version_from_names(node_managers_jar_zip_file.namelist())

    def _get_version_from_names(self, names):
        for name in names:
            match = re.search(BTSSM.BTSSM_VERSION_REGEXP, name)
            if match is not None:
                return match.group('version')
        return None

    def _get_node_managers_jar_path(self, installer_zip_file):
        installer_contents = installer_zip_file.namelist()
        for name in installer_contents:
            if re.match(BTSSM.NODE_MANAGERS_REGEXP, name):
                return name
        return None

    def _get_nested_zip_file(self, zip_file, zip_path):
        nested_zip_data = zip_file.read(zip_path)
        nested_zip_file = zipfile.ZipFile(StringIO(nested_zip_data))
        return nested_zip_file

    def _create_node_managers_check_command(self):
        return 'if [ -d "%s/NodeManagers" ]; then echo exists; else echo missing; fi' % self._install_location

    def _create_remote_jar_path(self, btssm_version):
        return path.join(self._install_location, 'NodeManagers', btssm_version, 'ltebtsmanager.jar')

    def _unpack_parameter_dictionary(self, jars_path, temp_path):
        cmd = BTSSM.UNZIP_PARAMETER_DICTIONARY.format(jars_path, temp_path)
        self._executor.run(cmd)

    def _remove_path(self, path):
        cmd = 'sudo rm -rf "{}"'.format(path)
        self._executor.run(cmd)
